local BreadMoldMaker = {}
local PRODUCTS = {
    iron_breadmold = { name = "Železni model za kruh", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni model za kruh za pekove." },
    bronze_breadmold = { name = "Bronast model za kruh", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast model za kruh za pekove." },
    silver_breadmold = { name = "Srebrn model za kruh", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn model za kruh za pekove." },
    gilded_breadmold = { name = "Pozlačen model za kruh", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen model za kruh za pekove." },
    jewel_set_breadmold = { name = "Draguljast model za kruh", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast model za kruh za pekove." },
    royal_sovereign_breadmold = { name = "Kraljevski suveren model za kruh", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren model za kruh z biseri za krono." },
}
local BUILDINGS = {
    breadmold_workshop = { name = "Breadmold delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    breadmold_house = { name = "Breadmold hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_breadmold_atelier = { name = "Mojstrski breadmold atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_breadmold_palace = { name = "Suverena breadmold palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
BreadMoldMaker.ironStock=12; BreadMoldMaker.bronzeStock=10; BreadMoldMaker.woodStock=16; BreadMoldMaker.leatherStock=8; BreadMoldMaker.silverStock=8; BreadMoldMaker.goldStock=6; BreadMoldMaker.jewelStock=4; BreadMoldMaker.pearlStock=4
BreadMoldMaker.productStock = {}; BreadMoldMaker.buildings = {}; BreadMoldMaker.maker = nil; BreadMoldMaker.activeMaking = {}; BreadMoldMaker.totalProducts = 0; BreadMoldMaker.dayTimer = 0
function BreadMoldMaker.init() BreadMoldMaker.ironStock=12; BreadMoldMaker.bronzeStock=10; BreadMoldMaker.woodStock=16; BreadMoldMaker.leatherStock=8; BreadMoldMaker.silverStock=8; BreadMoldMaker.goldStock=6; BreadMoldMaker.jewelStock=4; BreadMoldMaker.pearlStock=4; BreadMoldMaker.productStock={}; BreadMoldMaker.buildings={}; BreadMoldMaker.maker=nil; BreadMoldMaker.activeMaking={}; BreadMoldMaker.totalProducts=0; BreadMoldMaker.dayTimer=0; print("[BreadMoldMaker] Royal Bread Mold Maker System initialized (6 products, 4 buildings)") end
function BreadMoldMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BreadMoldMaker.maker={name=n or ("Modelar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Modelar najet: %s (spretnost: %d)",BreadMoldMaker.maker.name,s),"success") end; return true end
function BreadMoldMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BreadMoldMaker.build(id) local ok,e=BreadMoldMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BreadMoldMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BreadMoldMaker.getQualityBonus() local b=0; for _,bd in ipairs(BreadMoldMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BreadMoldMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and BreadMoldMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and BreadMoldMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and BreadMoldMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and BreadMoldMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and BreadMoldMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BreadMoldMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BreadMoldMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BreadMoldMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BreadMoldMaker.buildings==0 then return false,"Potrebna modelna delavnica" end; if not BreadMoldMaker.maker then return false,"Potreben modelar" end; return true end
function BreadMoldMaker.make(pt,qty) qty=qty or 1; local ok,e=BreadMoldMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then BreadMoldMaker.ironStock=BreadMoldMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then BreadMoldMaker.bronzeStock=BreadMoldMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then BreadMoldMaker.woodStock=BreadMoldMaker.woodStock-d.woodCost*qty end; if d.leatherCost then BreadMoldMaker.leatherStock=BreadMoldMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then BreadMoldMaker.silverStock=BreadMoldMaker.silverStock-d.silverCost*qty end; if d.goldCost then BreadMoldMaker.goldStock=BreadMoldMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BreadMoldMaker.jewelStock=BreadMoldMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BreadMoldMaker.pearlStock=BreadMoldMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BreadMoldMaker.maker then t=math.max(1,t-math.floor(BreadMoldMaker.maker.skill/13)) end; table.insert(BreadMoldMaker.activeMaking,{id="breadmold_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BreadMoldMaker.completeMaking(m) local q=1.0+(BreadMoldMaker.getQualityBonus()/100); if BreadMoldMaker.maker then q=q+(BreadMoldMaker.maker.skill/140) end; q=math.min(2.5,q); BreadMoldMaker.productStock[m.productType]=(BreadMoldMaker.productStock[m.productType] or 0)+m.quantity; BreadMoldMaker.totalProducts=BreadMoldMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BreadMoldMaker.maker then BreadMoldMaker.maker.itemsMade=BreadMoldMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BreadMoldMaker.maker.skill=math.min(100,BreadMoldMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Model izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"breadmold.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function BreadMoldMaker.update(dt) if not _G.state then return end; BreadMoldMaker.dayTimer=BreadMoldMaker.dayTimer+dt; if BreadMoldMaker.dayTimer>=30 then BreadMoldMaker.dayTimer=0; for i=#BreadMoldMaker.activeMaking,1,-1 do local m=BreadMoldMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BreadMoldMaker.completeMaking(m); table.remove(BreadMoldMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BreadMoldMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BreadMoldMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BreadMoldMaker.getStats() return {ironStock=BreadMoldMaker.ironStock,bronzeStock=BreadMoldMaker.bronzeStock,woodStock=BreadMoldMaker.woodStock,leatherStock=BreadMoldMaker.leatherStock,silverStock=BreadMoldMaker.silverStock,goldStock=BreadMoldMaker.goldStock,jewelStock=BreadMoldMaker.jewelStock,pearlStock=BreadMoldMaker.pearlStock,productStock=BreadMoldMaker.productStock,numBuildings=#BreadMoldMaker.buildings,hasMaker=BreadMoldMaker.maker~=nil,makerName=BreadMoldMaker.maker and BreadMoldMaker.maker.name or "—",makerSkill=BreadMoldMaker.maker and BreadMoldMaker.maker.skill or 0,activeMaking=#BreadMoldMaker.activeMaking,totalProducts=BreadMoldMaker.totalProducts} end
return BreadMoldMaker
